#!/usr/bin/env python3
"""Validate incidents.csv against schema.md (v0.1) and fill computed lag fields.

Usage:
    python validate.py data/incidents.csv            # validate, report problems
    python validate.py data/incidents.csv --write    # also rewrite computed columns in place

Exit code 0 if no errors (warnings allowed), 1 otherwise.
"""
import csv
import re
import sys
from datetime import date

REQUIRED = [
    "id", "developer", "system", "category", "severity", "date_occurred",
    "date_first_public", "first_public_via", "date_developer_disclosed",
    "would_meet_FMIR_definition", "summary", "sources", "verification_status",
    "entered_by", "entry_date",
]
ALL_COLUMNS = REQUIRED + [
    "secondary_categories", "date_detected", "disclosure_lag_days",
    "developer_lag_days", "developer_response", "notes", "last_reviewed",
]
CATEGORIES = {
    "weights_security", "scope_or_control", "capability_threshold",
    "mitigation_failure", "deception_in_eval", "harmful_output",
    "data_or_privacy", "other",
}
FIRST_PUBLIC_VIA = {
    "developer", "third_party_researcher", "press", "regulator",
    "user_report", "leak", "other", "unclear",
}
SEVERITY = {"1", "2", "3", "4", "unclear"}
YES_NO_UNCLEAR = {"yes", "no", "unclear"}
VERIFICATION = {"verified", "single_source", "disputed"}
ID_RE = re.compile(r"^(FIDT-\d{4}-\d{3}|EXAMPLE-\d{4}-\d{3})$")
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
URL_RE = re.compile(r"^https?://\S+$")


def parse_date(s):
    """Return a date, or None for 'unclear'/'none_found'/blank. Raise on bad format."""
    s = (s or "").strip()
    if s in ("", "unclear", "none_found"):
        return None
    if not DATE_RE.match(s):
        raise ValueError(f"bad date format {s!r}")
    y, m, d = map(int, s.split("-"))
    return date(y, m, d)


def lag(a, b):
    return "" if a is None or b is None else str((b - a).days)


def validate(path, write=False):
    errors, warnings = [], []
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        header = reader.fieldnames or []
        rows = list(reader)

    missing_cols = [c for c in REQUIRED if c not in header]
    if missing_cols:
        errors.append(f"header missing required columns: {missing_cols}")
        return errors, warnings, rows, header

    seen_ids = set()
    for n, row in enumerate(rows, start=2):  # line numbers incl. header
        where = f"line {n} ({row.get('id', '?')})"

        for col in REQUIRED:
            if not (row.get(col) or "").strip():
                errors.append(f"{where}: required field '{col}' is empty")

        rid = row.get("id", "")
        if rid and not ID_RE.match(rid):
            errors.append(f"{where}: id does not match FIDT-YYYY-NNN")
        if rid in seen_ids:
            errors.append(f"{where}: duplicate id")
        seen_ids.add(rid)
        if rid.startswith("EXAMPLE"):
            warnings.append(f"{where}: EXAMPLE row present — delete before release")

        if row.get("category") not in CATEGORIES:
            errors.append(f"{where}: unknown category {row.get('category')!r}")
        for sc in filter(None, (row.get("secondary_categories") or "").split("|")):
            if sc not in CATEGORIES:
                errors.append(f"{where}: unknown secondary category {sc!r}")
        if row.get("severity") not in SEVERITY:
            errors.append(f"{where}: severity must be 1-4 or unclear")
        if row.get("first_public_via") not in FIRST_PUBLIC_VIA:
            errors.append(f"{where}: unknown first_public_via {row.get('first_public_via')!r}")
        if row.get("would_meet_FMIR_definition") not in YES_NO_UNCLEAR:
            errors.append(f"{where}: would_meet_FMIR_definition must be yes/no/unclear")
        if row.get("verification_status") not in VERIFICATION:
            errors.append(f"{where}: unknown verification_status")

        # Dates and computed lags
        try:
            occurred = parse_date(row.get("date_occurred"))
            first_public = parse_date(row.get("date_first_public"))
            dev_disclosed = parse_date(row.get("date_developer_disclosed"))
            parse_date(row.get("date_detected"))
            parse_date(row.get("entry_date"))
            parse_date(row.get("last_reviewed"))
        except ValueError as e:
            errors.append(f"{where}: {e}")
            occurred = first_public = dev_disclosed = None

        if occurred and first_public and first_public < occurred:
            errors.append(f"{where}: date_first_public is before date_occurred")
        if occurred and dev_disclosed and dev_disclosed < occurred:
            errors.append(f"{where}: date_developer_disclosed is before date_occurred")
        if first_public and dev_disclosed and dev_disclosed < first_public:
            warnings.append(
                f"{where}: developer disclosed before first_public date — "
                "then first_public_via should probably be 'developer'"
            )
        if row.get("first_public_via") == "developer" and row.get("date_developer_disclosed") in ("none_found", "unclear"):
            warnings.append(f"{where}: first_public_via=developer but no developer disclosure date")

        row["disclosure_lag_days"] = lag(occurred, first_public)
        row["developer_lag_days"] = lag(occurred, dev_disclosed)

        # Sources
        sources = [s for s in (row.get("sources") or "").split("|") if s.strip()]
        for s in sources:
            if not URL_RE.match(s.strip()):
                errors.append(f"{where}: source is not a URL: {s!r}")
        if row.get("verification_status") == "verified" and len(sources) < 2:
            errors.append(f"{where}: 'verified' requires at least 2 sources (has {len(sources)})")
        if row.get("verification_status") != "verified" and len(sources) >= 2:
            warnings.append(f"{where}: has {len(sources)} sources but is not marked verified")

        # Summary length
        words = len((row.get("summary") or "").split())
        if words > 60:
            warnings.append(f"{where}: summary is {words} words (limit 60)")
        if row.get("would_meet_FMIR_definition") == "unclear" and not (row.get("notes") or "").strip():
            warnings.append(f"{where}: would_meet_FMIR_definition=unclear but notes are empty")

    if write and not errors:
        cols = [c for c in header] + [c for c in ALL_COLUMNS if c not in header]
        with open(path, "w", newline="", encoding="utf-8") as f:
            w = csv.DictWriter(f, fieldnames=cols)
            w.writeheader()
            w.writerows(rows)

    return errors, warnings, rows, header


def main(argv):
    if len(argv) < 2:
        print(__doc__)
        return 2
    path = argv[1]
    write = "--write" in argv
    errors, warnings, rows, _ = validate(path, write=write)
    real = [r for r in rows if not r.get("id", "").startswith("EXAMPLE")]
    verified = [r for r in real if r.get("verification_status") == "verified"]
    print(f"{len(real)} real rows ({len(verified)} verified), {len(rows) - len(real)} example rows")
    for w in warnings:
        print("WARN ", w)
    for e in errors:
        print("ERROR", e)
    if errors:
        print(f"\n{len(errors)} error(s).")
        return 1
    print("\nOK" + (" — computed columns written." if write else ""))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
